// Numark NS7II mapping for Mixxx (2.3 or newer), generated by `ns7iid mixxx-map`.
//
// Everything hardware-specific lives in NS7II.MAP below, produced from a
// guided capture of the real unit by the ns7iid Linux driver. The code is
// a static template that builds Mixxx components from that map, so it can
// be edited freely; re-running mixxx-map only replaces the MAP block.
//
// Requires midi-components-0.0.js (shipped with Mixxx).

/* eslint-disable */
var NS7II = {};

NS7II.MAP = /*__MAP__*/{};

NS7II.settings = {
    invertPitch: true,          // pitch fader: + at the bottom (set false if pitch runs backwards)
    platterTicks: 3600,         // ticks per platter revolution (Numark: 3600)
    scratchAlpha: 1.0 / 8,
    scratchBeta: 1.0 / 8 / 32,
    jogSensitivity: 40,         // jog (non-vinyl) ticks per "jog" unit
    loopSizes: [0.125, 0.25, 0.5, 1, 2, 4, 8, 16],
    jumpSizes: [1, 2, 4, 8],
    browseAccel: 5,             // rows per click with SHIFT
};

NS7II.camel = function(id) {
    if (id === "shift") { return "shiftButton"; }   // must not shadow ComponentContainer.shift()
    return id.replace(/_([a-z0-9])/g, function(_, c) { return c.toUpperCase(); });
};

// Relative encoder/platter value -> signed delta for the two common conventions.
NS7II.relDelta = function(value, mode) {
    if (mode === "rel64") { return value - 64; }
    return value < 64 ? value : value - 128;   // two's complement
};

NS7II.shiftState = [false, false];   // per side (left: decks 1/3, right: decks 2/4)

NS7II.setShift = function(side, on) {
    NS7II.shiftState[side] = on;
    NS7II.decks.forEach(function(d) {
        if (d.side === side) { on ? d.shift() : d.unshift(); }
    });
    on ? NS7II.master.shift() : NS7II.master.unshift();
};

// Controls in the map that this template has no handler for get a silent
// component, so every XML binding resolves and nothing is reported as an error.
NS7II.fillUnhandled = function(container, controls) {
    Object.keys(controls).forEach(function(id) {
        var name = NS7II.camel(id);
        if (container[name] === undefined) {
            container[name] = new components.Component({midi: controls[id].midi, input: function() {}, inputMSB: function() {}, inputLSB: function() {}});
        }
    });
};

// ---------------------------------------------------------------- Deck

NS7II.Deck = function(desc) {
    components.Deck.call(this, [desc.number]);
    var deck = this;
    var n = desc.number;
    var c = desc.controls;
    this.number = n;
    this.side = (n % 2 === 1) ? 0 : 1;
    this.group = "[Channel" + n + "]";
    this.vinylMode = true;
    this.padMode = "hotcue";
    this.loopRoot = 0;   // index offset into loopSizes
    var fxUnit = this.side + 1;
    var samplerBase = this.side * 8;

    var has = function(id) { return c[id] !== undefined; };
    var midiOf = function(id) { return c[id].midi; };
    var add = function(id, comp) { deck[NS7II.camel(id)] = comp; return comp; };
    var simpleButton = function(id, key, toggle, group) {
        if (!has(id)) { return; }
        var opts = {midi: midiOf(id), key: key, group: group || deck.group};
        if (toggle) { opts.type = components.Button.prototype.types.toggle; }
        add(id, new components.Button(opts));
    };
    var pot = function(id, group, inKey, invert) {
        if (!has(id)) { return; }
        var b = c[id];
        if (b.type === "encoder") {
            // Endless knob: step the parameter by 1/64 per click.
            add(id, new components.Encoder({
                midi: b.midi, group: group, inKey: inKey,
                input: function(channel, control, value) {
                    var d = NS7II.relDelta(value, "rel2c");
                    if (Math.abs(d) > 32) { d = NS7II.relDelta(value, "rel64"); }
                    var v = engine.getParameter(this.group, this.inKey) + d / 64;
                    engine.setParameter(this.group, this.inKey, Math.max(0, Math.min(1, v)));
                },
            }));
            return;
        }
        var opts = {midi: b.midi, group: group, inKey: inKey, invert: !!invert};
        var p = new components.Pot(opts);
        if (b.type === "pitchbend") {
            p.input = function(channel, control, value, status, g) {
                var v14 = (value << 7) | control;
                this.max = 16383;
                components.Pot.prototype.input.call(this, channel, control, v14, status, g);
            };
        }
        add(id, p);
    };

    if (has("play")) { add("play", new components.PlayButton({midi: midiOf("play")})); }
    if (has("cue")) { add("cue", new components.CueButton({midi: midiOf("cue")})); }
    if (has("sync")) { add("sync", new components.SyncButton({midi: midiOf("sync")})); }
    simpleButton("keylock", "keylock", true);
    simpleButton("slip", "slip_enabled", true);
    simpleButton("censor", "reverseroll", false);
    simpleButton("reverse", "reverse", true);
    simpleButton("pitch_bend_minus", "rate_temp_down", false);
    simpleButton("pitch_bend_plus", "rate_temp_up", false);
    simpleButton("loop_in", "loop_in", false);
    simpleButton("loop_out", "loop_out", false);
    simpleButton("loop_toggle", "reloop_toggle", false);
    simpleButton("loop_half", "loop_halve", false);
    simpleButton("loop_double", "loop_double", false);
    simpleButton("load", "LoadSelectedTrack", false);
    simpleButton("deck_select", "", false);
    simpleButton("tap", "bpm_tap", false);
    simpleButton("grid_adjust", "beats_translate_curpos", false);
    simpleButton("grid_slip", "beats_translate_match_alignment", false);
    pot("rate", this.group, "rate", NS7II.settings.invertPitch);
    for (var hc = 1; hc <= 5; hc++) {
        if (has("hotcue" + hc)) {
            add("hotcue" + hc, new components.HotcueButton({midi: midiOf("hotcue" + hc), number: hc, group: this.group}));
        }
    }

    if (has("range")) {
        add("range", new components.Button({
            midi: midiOf("range"),
            ranges: [0.08, 0.16, 0.5, 1.0],
            input: function(channel, control, value, status) {
                if (!this.isPress(channel, control, value, status)) { return; }
                var cur = engine.getValue(deck.group, "rateRange");
                var i = 0;
                while (i < this.ranges.length && this.ranges[i] <= cur + 0.001) { i++; }
                engine.setValue(deck.group, "rateRange", this.ranges[i % this.ranges.length]);
            },
        }));
    }

    if (has("shift")) {
        add("shift", new components.Button({
            midi: midiOf("shift"),
            input: function(channel, control, value, status) {
                NS7II.setShift(deck.side, this.isPress(channel, control, value, status));
            },
        }));
    }

    // Platter: touch = scratch enable, turn = ticks.
    if (has("platter_touch")) {
        add("platter_touch", new components.Button({
            midi: midiOf("platter_touch"),
            input: function(channel, control, value, status) {
                if (this.isPress(channel, control, value, status)) {
                    if (deck.vinylMode) {
                        engine.scratchEnable(n, NS7II.settings.platterTicks, 33 + 1 / 3,
                            NS7II.settings.scratchAlpha, NS7II.settings.scratchBeta);
                    }
                } else {
                    engine.scratchDisable(n);
                }
            },
        }));
    }
    if (has("platter_turn")) {
        var pl = c["platter_turn"];
        var platter = new components.Component({
            midi: pl.midi,
            last: null,
            msb: null,
            delta: function(value) {
                if (pl.mode === "relative" || pl.mode === "rel64" || pl.mode === "rel2c") {
                    return NS7II.relDelta(value, pl.mode === "rel64" ? "rel64" : "rel2c");
                }
                var span = pl.lsb ? NS7II.settings.platterTicks : 128;
                if (this.last === null) { this.last = value; return 0; }
                var d = value - this.last;
                this.last = value;
                if (d > span / 2) { d -= span; } else if (d < -span / 2) { d += span; }
                return d;
            },
            apply: function(d) {
                if (d === 0) { return; }
                if (engine.isScratching(n)) {
                    engine.scratchTick(n, d);
                } else if (NS7II.shiftState[deck.side]) {
                    engine.setValue(deck.group, "beatjump", d > 0 ? 1 : -1);
                } else {
                    engine.setValue(deck.group, "jog", d / NS7II.settings.jogSensitivity);
                }
            },
            input: function(channel, control, value) {
                if (pl.lsb) {
                    // 14-bit absolute: wait for LSB.
                    this.msb = value;
                    return;
                }
                this.apply(this.delta(value));
            },
            inputLSB: function(channel, control, value) {
                if (this.msb === null) { return; }
                var v = (this.msb << 7) | value;
                this.apply(this.delta(v));
            },
        });
        add("platter_turn", platter);
    }

    if (has("strip")) {
        var st = c["strip"];
        add("strip", new components.Pot({
            midi: st.midi,
            group: this.group,
            inKey: "playposition",
            max: st.lsb ? 16383 : 127,
            msb: null,
            input: function(channel, control, value, status, g) {
                if (st.lsb) { this.msb = value; return; }
                this.apply(value, channel, control, status, g);
            },
            inputLSB: function(channel, control, value, status, g) {
                if (this.msb === null) { return; }
                this.apply((this.msb << 7) | value, channel, control, status, g);
            },
            apply: function(v, channel, control, status, g) {
                // Needle drop only while stopped, unless SHIFT is held.
                if (!engine.getValue(deck.group, "play") || NS7II.shiftState[deck.side]) {
                    components.Pot.prototype.input.call(this, channel, control, v, status, g);
                }
            },
        }));
    }

    if (has("motor")) {
        add("motor", new components.Button({
            midi: midiOf("motor"),
            input: function(channel, control, value, status) {
                if (this.isPress(channel, control, value, status)) {
                    deck.vinylMode = !deck.vinylMode;
                    this.send(deck.vinylMode ? 0x7F : 0x00);
                }
            },
        }));
    }

    if (has("loop_encoder")) {
        var le = c["loop_encoder"];
        add("loop_encoder", new components.Encoder({
            midi: le.midi,
            input: function(channel, control, value) {
                var d = NS7II.relDelta(value, "rel2c");
                if (Math.abs(d) > 32) { d = NS7II.relDelta(value, "rel64"); }
                engine.setValue(deck.group, d > 0 ? "loop_double" : "loop_halve", 1);
            },
        }));
    }

    // Pad modes.
    var modes = {pad_mode_cue: "hotcue", pad_mode_autoloop: "loop", pad_mode_loop: "manualloop", pad_mode_slicer: "slicer", pad_mode_sampler: "sampler"};
    // Manual loop mode: pad -> control, press only.
    var manualLoop = ["loop_in", "loop_out", "reloop_toggle", "reloop_andstop", "loop_halve", "loop_double", "loop_move_1_backward", "loop_move_1_forward"];
    Object.keys(modes).forEach(function(id) {
        if (!has(id)) { return; }
        add(id, new components.Button({
            midi: midiOf(id),
            mode: modes[id],
            input: function(channel, control, value, status) {
                if (this.isPress(channel, control, value, status)) {
                    deck.setPadMode(this.mode);
                }
            },
        }));
    });
    this.setPadMode = function(mode) {
        deck.padMode = mode;
        Object.keys(modes).forEach(function(id) {
            var b = deck[NS7II.camel(id)];
            if (b) { b.send(modes[id] === mode ? 0x7F : 0x00); }
        });
        deck.refreshPads();
    };

    this.pads = [];
    for (var i = 1; i <= 8; i++) {
        (function(i) {
            var id = "pad" + i;
            if (!has(id)) { return; }
            var pad = new components.Button({
                midi: midiOf(id),
                index: i,
                input: function(channel, control, value, status) {
                    var press = this.isPress(channel, control, value, status);
                    var shift = NS7II.shiftState[deck.side];
                    var g = deck.group;
                    switch (deck.padMode) {
                    case "hotcue":
                        if (shift) {
                            if (press) { engine.setValue(g, "hotcue_" + i + "_clear", 1); }
                        } else {
                            engine.setValue(g, "hotcue_" + i + "_activate", press ? 1 : 0);
                        }
                        break;
                    case "loop":
                        if (press) {
                            var size = NS7II.settings.loopSizes[(i - 1 + deck.loopRoot) % NS7II.settings.loopSizes.length];
                            engine.setValue(g, shift ? "beatlooproll_" + size + "_activate" : "beatloop_" + size + "_toggle", 1);
                        } else if (shift) {
                            var size2 = NS7II.settings.loopSizes[(i - 1 + deck.loopRoot) % NS7II.settings.loopSizes.length];
                            engine.setValue(g, "beatlooproll_" + size2 + "_activate", 0);
                        }
                        break;
                    case "slicer":
                        if (press) {
                            var js = NS7II.settings.jumpSizes[(i - 1) % 4];
                            engine.setValue(g, "beatjump_" + js + (i <= 4 ? "_backward" : "_forward"), 1);
                        }
                        break;
                    case "manualloop":
                        if (press) { engine.setValue(g, manualLoop[i - 1], 1); }
                        break;
                    case "sampler":
                        var sg = "[Sampler" + (samplerBase + i) + "]";
                        if (press) {
                            if (shift) {
                                engine.setValue(sg, "stop", 1);
                            } else if (engine.getValue(sg, "track_loaded")) {
                                engine.setValue(sg, "cue_gotoandplay", 1);
                            } else {
                                engine.setValue(sg, "LoadSelectedTrack", 1);
                            }
                        }
                        break;
                    }
                    deck.refreshPad(i);
                },
            });
            deck.pads[i - 1] = pad;
            add(id, pad);
        })(i);
    }
    this.refreshPad = function(i) {
        var pad = deck.pads[i - 1];
        if (!pad) { return; }
        var g = deck.group;
        var on = false;
        switch (deck.padMode) {
        case "hotcue": on = engine.getValue(g, "hotcue_" + i + "_status") > 0; break;
        case "loop":
            var size = NS7II.settings.loopSizes[(i - 1 + deck.loopRoot) % NS7II.settings.loopSizes.length];
            on = engine.getValue(g, "beatloop_" + size + "_enabled") > 0;
            break;
        case "slicer": on = true; break;
        case "manualloop": on = (i <= 4) ? engine.getValue(g, "loop_enabled") > 0 : true; break;
        case "sampler": on = engine.getValue("[Sampler" + (samplerBase + i) + "]", "play") > 0; break;
        }
        pad.send(on ? 0x7F : 0x00);
    };
    this.refreshPads = function() { for (var i = 1; i <= 8; i++) { deck.refreshPad(i); } };
    this.padConnections = [];
    for (var h = 1; h <= 8; h++) {
        this.padConnections.push(engine.makeConnection(this.group, "hotcue_" + h + "_status", function() { deck.refreshPads(); }));
        this.padConnections.push(engine.makeConnection("[Sampler" + (samplerBase + h) + "]", "play", function() { deck.refreshPads(); }));
    }
    NS7II.settings.loopSizes.forEach(function(size) {
        deck.padConnections.push(engine.makeConnection(deck.group, "beatloop_" + size + "_enabled", function() { deck.refreshPads(); }));
    });
    this.padConnections.push(engine.makeConnection(this.group, "loop_enabled", function() { deck.refreshPads(); }));

    var param = function(id, dir) {
        if (!has(id)) { return; }
        add(id, new components.Button({
            midi: midiOf(id),
            input: function(channel, control, value, status) {
                if (!this.isPress(channel, control, value, status)) { return; }
                switch (deck.padMode) {
                case "loop":
                    deck.loopRoot = Math.max(0, Math.min(NS7II.settings.loopSizes.length - 1, deck.loopRoot + dir));
                    deck.refreshPads();
                    break;
                case "hotcue":
                    engine.setValue(deck.group, "beatjump", dir);
                    break;
                case "slicer":
                    engine.setValue(deck.group, dir > 0 ? "beatjump_size_double" : "beatjump_size_halve", 1);
                    break;
                }
            },
        }));
    };
    param("param_left", -1);
    param("param_right", 1);

    // FX unit for this side.
    var unitGroup = "[EffectRack1_EffectUnit" + fxUnit + "]";
    for (var k = 1; k <= 3; k++) {
        var eg = "[EffectRack1_EffectUnit" + fxUnit + "_Effect" + k + "]";
        simpleButton("fx" + k + "_on", "enabled", true, eg);
        pot("fx" + k + "_knob", eg, "meta", false);
    }
    if (has("fx_beats")) {
        add("fx_beats", new components.Encoder({
            midi: midiOf("fx_beats"),
            input: function(channel, control, value) {
                var d = NS7II.relDelta(value, "rel2c");
                if (Math.abs(d) > 32) { d = NS7II.relDelta(value, "rel64"); }
                var mix = engine.getValue(unitGroup, "mix") + d * 0.05;
                engine.setValue(unitGroup, "mix", Math.max(0, Math.min(1, mix)));
            },
        }));
    }
    simpleButton("fx_tap", "next_chain", false, unitGroup);
    simpleButton("fx_assign", "group_" + this.group + "_enable", true, unitGroup);

    NS7II.fillUnhandled(this, c);
    this.reconnectComponents(function(comp) {
        if (comp.group === undefined) { comp.group = deck.group; }
    });
    this.setPadMode("hotcue");
};
NS7II.Deck.prototype = Object.create(components.Deck.prototype);

// ---------------------------------------------------------------- Mixer channel

NS7II.MixerChannel = function(desc) {
    components.ComponentContainer.call(this);
    var n = desc.number;
    var c = desc.controls;
    var self = this;
    var group = "[Channel" + n + "]";
    var eq = "[EqualizerRack1_" + group + "_Effect1]";
    var qf = "[QuickEffectRack1_" + group + "]";
    var pot = function(id, g, inKey) {
        if (!c[id]) { return; }
        self[NS7II.camel(id)] = new components.Pot({midi: c[id].midi, group: g, inKey: inKey});
    };
    pot("gain", group, "pregain");
    pot("treble", eq, "parameter3");
    pot("mid", eq, "parameter2");
    pot("bass", eq, "parameter1");
    pot("filter", qf, "super1");
    pot("fader", group, "volume");
    if (c["pfl"]) {
        this.pfl = new components.Button({midi: c["pfl"].midi, group: group, key: "pfl", type: components.Button.prototype.types.toggle});
    }
    // FX ASSIGN A/B: route this channel into effect unit 1/2.
    ["fx_a", "fx_b"].forEach(function(id, k) {
        if (!c[id]) { return; }
        self[NS7II.camel(id)] = new components.Button({
            midi: c[id].midi, group: "[EffectRack1_EffectUnit" + (k + 1) + "]", key: "group_" + group + "_enable",
            type: components.Button.prototype.types.toggle,
        });
    });
    // Crossfader assign switch: A = left, B = right, neither = centre (bypass).
    var xf = function(id, side) {
        if (!c[id]) { return; }
        self[NS7II.camel(id)] = new components.Button({
            midi: c[id].midi,
            input: function(channel, control, value, status) {
                engine.setValue(group, "orientation", this.isPress(channel, control, value, status) ? side : 1);
            },
        });
    };
    xf("xf_a", 0);
    xf("xf_b", 2);
    NS7II.fillUnhandled(this, c);
};
NS7II.MixerChannel.prototype = Object.create(components.ComponentContainer.prototype);

// ---------------------------------------------------------------- Master / library

NS7II.Master = function(c) {
    components.ComponentContainer.call(this);
    var self = this;
    var pot = function(id, g, inKey) {
        if (!c[id]) { return; }
        self[NS7II.camel(id)] = new components.Pot({midi: c[id].midi, group: g, inKey: inKey});
    };
    pot("crossfader", "[Master]", "crossfader");
    pot("master", "[Master]", "gain");
    pot("booth", "[Master]", "booth_gain");
    pot("cue_gain", "[Master]", "headGain");
    pot("cue_mix", "[Master]", "headMix");
    pot("mic", "[Microphone]", "pregain");
    pot("mic_bass", "[EqualizerRack1_[Microphone]_Effect1]", "parameter1");
    pot("mic_treble", "[EqualizerRack1_[Microphone]_Effect1]", "parameter3");
    if (c["sampler_vol"]) {
        this.samplerVol = new components.Pot({
            midi: c["sampler_vol"].midi,
            inSetParameter: function(v) {
                for (var i = 1; i <= 16; i++) { engine.setParameter("[Sampler" + i + "]", "pregain", v); }
            },
        });
    }
    if (c["browse_turn"]) {
        this.browseTurn = new components.Encoder({
            midi: c["browse_turn"].midi,
            input: function(channel, control, value) {
                var d = NS7II.relDelta(value, "rel2c");
                if (Math.abs(d) > 32) { d = NS7II.relDelta(value, "rel64"); }
                var step = (NS7II.shiftState[0] || NS7II.shiftState[1]) ? NS7II.settings.browseAccel : 1;
                engine.setValue("[Library]", "MoveVertical", d * step);
            },
        });
    }
    var btn = function(id, g, key, toggle) {
        if (!c[id]) { return; }
        var opts = {midi: c[id].midi, group: g, key: key};
        if (toggle) { opts.type = components.Button.prototype.types.toggle; }
        self[NS7II.camel(id)] = new components.Button(opts);
    };
    btn("browse_push", "[Library]", "GoToItem");
    btn("back", "[Library]", "MoveFocusBackward");
    btn("fwd", "[Library]", "MoveFocusForward");
    btn("view", "[Master]", "maximize_library", true);
    btn("load_prepare", "[Library]", "AutoDjAddBottom");
    btn("crates", "[Library]", "MoveFocusBackward");
    btn("files", "[Library]", "MoveFocusForward");
    btn("prepare", "[AutoDJ]", "enabled", true);
    btn("master_fx_a", "[EffectRack1_EffectUnit1]", "group_[Master]_enable", true);
    btn("master_fx_b", "[EffectRack1_EffectUnit2]", "group_[Master]_enable", true);
    // Front-panel switches: the position is the state.
    var sw = function(id, g, key) {
        if (!c[id]) { return; }
        self[NS7II.camel(id)] = new components.Button({
            midi: c[id].midi,
            input: function(channel, control, value, status) {
                engine.setValue(g, key, this.isPress(channel, control, value, status) ? 1 : 0);
            },
        });
    };
    sw("split_cue", "[Master]", "headSplit");
    sw("mic_on", "[Microphone]", "talkover");
    NS7II.fillUnhandled(this, c);
};
NS7II.Master.prototype = Object.create(components.ComponentContainer.prototype);

// ---------------------------------------------------------------- Lifecycle

NS7II.init = function(id, debugging) {
    NS7II.decks = NS7II.MAP.decks.map(function(d) { return new NS7II.Deck(d); });
    NS7II.mixer = NS7II.MAP.mixer.map(function(m) { return new NS7II.MixerChannel(m); });
    NS7II.master = new NS7II.Master(NS7II.MAP.master || {});
    console.log("NS7II mapping loaded: " + NS7II.decks.length + " decks, " + NS7II.mixer.length + " mixer channels");
};

NS7II.shutdown = function() {
    // Turn off every LED we know about.
    var off = function(desc) {
        Object.keys(desc.controls || desc).forEach(function(id) {
            var b = (desc.controls || desc)[id];
            if (b && b.type === "button") { midi.sendShortMsg(b.midi[0], b.midi[1], 0x00); }
        });
    };
    NS7II.MAP.decks.forEach(off);
    NS7II.MAP.mixer.forEach(off);
    off(NS7II.MAP.master || {});
};
